(() => {
// A real submission is acknowledged only when the configured server explicitly accepts it.
const form=document.querySelector('#enquiry-form');
const formStatus=document.querySelector('#form-status');
const submitButton=document.querySelector('#submit-enquiry');
const endpoint=(window.STUDIO_CONFIG?.enquiryEndpoint||'').trim();
if(endpoint)document.querySelector('#form-note').textContent='All four fields are required. Your details will be used to respond to your enquiry.';
function validateField(input){const value=input.value.trim();let error='';if(!value)error=({name:'Please enter your name.',email:'Please enter your email address.',phone:'Please enter your phone number.',message:'Please tell us a little about your project.'})[input.name];else if(input.name==='email'&&(input.validity.typeMismatch||!/^\S+@[^\s@]+\.[^\s@]+$/.test(value)))error='Please enter a valid email address.';else if(input.name==='phone'&&(!/^\+?[\d\s().-]+$/.test(value)||value.replace(/\D/g,'').length<7||value.replace(/\D/g,'').length>15))error='Use 7–15 digits, with an optional country code.';document.querySelector('#'+input.id+'-error').textContent=error;input.setAttribute('aria-invalid',String(Boolean(error)));return !error;}
const fields=[...form.querySelectorAll('input,textarea')];
fields.forEach(field=>{field.addEventListener('blur',()=>validateField(field));field.addEventListener('input',()=>{if(field.getAttribute('aria-invalid')==='true')validateField(field);formStatus.textContent='';});});
function validateForm(){const results=fields.map(validateField);const invalid=fields.find(f=>f.getAttribute('aria-invalid')==='true');if(invalid)invalid.focus();return results.every(Boolean);}
function setStatus(text,state){formStatus.textContent=text;formStatus.dataset.state=state;}
function enquiryData(){return Object.fromEntries(fields.map(f=>[f.name,f.value.trim()]));}
form.addEventListener('submit',async e=>{e.preventDefault();if(!validateForm()){setStatus('Please check the highlighted fields.','error');return;}if(!endpoint){setStatus('Your enquiry has not been sent. Online submissions are not connected yet. You can use “Copy enquiry” to keep your details.','error');return;}let url;try{url=new URL(endpoint,location.origin);if(url.protocol!=='https:'&&url.origin!==location.origin)throw new Error('Invalid endpoint');}catch{setStatus('Online submissions are unavailable. Your enquiry has not been sent.','error');return;}submitButton.disabled=true;submitButton.textContent='Sending enquiry…';form.setAttribute('aria-busy','true');setStatus('Sending your enquiry…','loading');const abort=new AbortController();const timer=setTimeout(()=>abort.abort(),15000);try{const response=await fetch(url.href,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(enquiryData()),signal:abort.signal,credentials:'omit'});const result=await response.json();if(!response.ok||result.success!==true)throw new Error('Enquiry was not accepted');form.reset();fields.forEach(f=>{f.removeAttribute('aria-invalid');document.querySelector('#'+f.id+'-error').textContent='';});setStatus('Thank you. Your enquiry has been received by the studio.','success');}catch(error){setStatus(error.name==='AbortError'?'The request timed out. Delivery could not be confirmed. Please check before trying again.':'We couldn’t confirm delivery. Your details are still here; please try again or copy your enquiry.','error');}finally{clearTimeout(timer);submitButton.disabled=false;submitButton.innerHTML='Submit Enquiry <span aria-hidden="true">↗</span>';form.removeAttribute('aria-busy');}});
document.querySelector('#copy-enquiry').addEventListener('click',async()=>{if(!validateForm())return;const data=enquiryData();const text=`Interior design enquiry — Ashtavinayak Design\n\nName: ${data.name}\nEmail: ${data.email}\nPhone: ${data.phone}\n\n${data.message}`;try{await navigator.clipboard.writeText(text);setStatus('Enquiry copied. Nothing has been sent to the studio.','info');}catch{setStatus('Clipboard access is unavailable. Please select and copy your details manually. Nothing has been sent.','error');}});


})();
